create temporary table batch_input as select * from jsonb_to_recordset($data$[{"available": true, "details": "\nHighlights\nMaterials: Linen\n\nNotes:\nMaterial: Linen\nStyle: Gingham\nHeading Style: Hooks/Rod Pocket/Grommet\nTIPS: The curtain in the picture shows a double-pleated effect. To achieve the same look, you\u2019ll need to order twice the width of your window size.\nColor difference: Colors may look slightly different depending on monitor settings.\nPlease note that the default order includes one curtain panel. If you would like two panels, please select a quantity of 2 when placing your order. Thank you!\n\nThese cozy window curtains are designed to create a soft and relaxed atmosphere while adding visual texture to your space. They can be used as bedroom curtains, living room window treatments, farmhouse curtains, cottage curtains or decorative panels for a cozy country-inspired home. The understated vintage pattern makes them easy to coordinate with both neutral and warm-toned interiors, while the relaxed drape gives the room a comfortable, lived-in feeling. Whether you are refreshing a farmhouse bedroom, creating a charming cottage retreat or adding rustic character to your living space, these plaid curtains offer an easy way to bring timeless country style and everyday warmth into your home. Please contact us if you need a custom size or have questions about the available options.\n\nLess\n", "images": [{"alt": "May include: A pinch pleat curtain panel featuring a light beige and white checkered pattern. The fabric hangs from a metallic bronze curtain rod with circular rings, creating vertical folds that extend down the length of the window treatment.", "src": "https://i.etsystatic.com/45174159/r/il/c29fd8/8700404825/il_1588xN.8700404825_adm0.jpg"}, {"alt": "May include: A fabric curtain featuring a light beige and white checkered gingham pattern. The material has a visible woven texture with vertical folds creating depth. A small inset shows a magnified view of the fabric weave and pattern.", "src": "https://i.etsystatic.com/45174159/r/il/a299ba/8652577584/il_794xN.8652577584_6xrv.jpg"}], "shops": [{"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL?ref=shop-header-name&listing_id=4556211571&from_page=listing"}, {"text": "", "url": "https://www.etsy.com/shop/WOGOL?ref=l2-about-shopname&from_page=listing"}], "title": "Vintage Rustic Linen Plaid Curtains, Cozy Gingham Semi Blackout Window Drapes", "source_url": "https://www.etsy.com/listing/4556211571/vintage-rustic-linen-plaid-curtains-cozy", "checked_at": "2026-10-13T05:23:07.945Z", "account": "P1", "shop": "WOGOL", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "a16a2801ab0284627daa6188c078b34e7f4dfe57e62a2f105e79a8ab1adb0916"}, "listing_id": "4556211571", "new_title": "Beige Gingham Curtain Panel", "body": "A subtle beige and white check pattern adds cottage character to this WOGOL curtain panel. The listing offers several hanging styles and sizes. Sold as one panel; see Etsy for options.", "facebook_draft": "Beige Gingham Curtain Panel \u2014 A subtle beige and white check pattern adds cottage character to this WOGOL curtain panel. The listing offers several hanging styles and sizes. Sold as one panel; see Etsy for options. Browse: https://www.etsy.com/listing/4556211571/vintage-rustic-linen-plaid-curtains-cozy", "image_url": "https://i.etsystatic.com/45174159/r/il/c29fd8/8700404825/il_1588xN.8700404825_adm0.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "icyndizhang", "board_id": "801218658646993070", "board_name": "CyndiZhangStudio", "category": "Curtains", "board_inspection_run": "38351026265"}, {"available": true, "details": "\nHighlights\nMade by WOGOL\nMaterials: Linen\n\nNotes:\nMaterial: Linen\nColor: blue white stripe\nHeading Style: Hooks/Rod Pocket/Grommet\nTIPS: The curtain in the picture shows a double-pleated effect. To achieve the same look, you\u2019ll need to order twice the width of your window size.\nColor difference: Colors may look slightly different depending on monitor settings.\nPlease note that the default order includes one curtain panel. If you would like two panels, please select a quantity of 2 when placing your order. Thank you!\n\nCreate a relaxed and effortlessly stylish home with these linen striped curtains, designed to bring natural texture and a laid-back atmosphere to your space. The combination of a linen-inspired texture and classic stripes creates an easygoing look that feels warm, casual and timeless. Instead of a perfectly formal appearance, the fabric drapes softly and naturally, adding gentle folds and an organic sense of movement to the window. This relaxed style works beautifully with INS-inspired interiors, natural home decor, modern farmhouse spaces, American country style and light French-inspired rooms. The classic stripe pattern adds visual interest without overwhelming the space, making these curtains easy to pair with wood furniture, woven accents, neutral walls, vintage pieces and other natural textiles.\n\nLess\n", "images": [{"alt": "May include: A pinch pleat curtain panel featuring vertical stripes in shades of blue, beige, and cream. The fabric hangs from a metallic curtain rod with rings, creating uniform folds that extend from the top header to the bottom edge.", "src": "https://i.etsystatic.com/45174159/r/il/86ac1b/8652555320/il_1588xN.8652555320_shqd.jpg"}, {"alt": "May include: A woven fabric featuring a vertical striped pattern in shades of light blue, beige, and grey on an off-white background. The material has a visible textured weave, and the stripes vary in width and color intensity across the surface.", "src": "https://i.etsystatic.com/45174159/r/il/6b5736/8700381547/il_794xN.8700381547_h3zw.jpg"}], "shops": [{"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL?ref=shop-header-name&listing_id=4556220466&from_page=listing"}, {"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL"}], "title": "Blue Striped Linen Curtains, Semi-Blackout Window Drapes, English Cottage Style", "source_url": "https://www.etsy.com/listing/4556220466/blue-striped-linen-curtains-semi", "checked_at": "2026-10-13T05:23:16.199Z", "account": "P1", "shop": "WOGOL", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "27609ed2fac1c181f2e3c325dede614c13777c858f335b888e2ad8c814d305a5"}, "listing_id": "4556220466", "new_title": "Blue and Cream Striped Curtain Panel", "body": "Blue and cream vertical stripes bring a relaxed cottage look to this WOGOL curtain. Available hanging styles are listed on Etsy. The default order is one panel.", "facebook_draft": "Blue and Cream Striped Curtain Panel \u2014 Blue and cream vertical stripes bring a relaxed cottage look to this WOGOL curtain. Available hanging styles are listed on Etsy. The default order is one panel. Browse: https://www.etsy.com/listing/4556220466/blue-striped-linen-curtains-semi", "image_url": "https://i.etsystatic.com/45174159/r/il/86ac1b/8652555320/il_1588xN.8652555320_shqd.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "icyndizhang", "board_id": "801218658646993070", "board_name": "CyndiZhangStudio", "category": "Curtains", "board_inspection_run": "38351026265"}, {"available": true, "details": "\nHighlights\nMaterials: Cotton, linen\n\nNotes:\nMaterial: Cotton Linen\nColor: Yellow stripe\nHeading Style: Hooks/Rod Pocket/Grommet\nColor difference: Colors may look slightly different depending on monitor settings.\nPlease note that the default order includes one curtain panel. If you would like two panels, please select a quantity of 2 when placing your order. Thank you!\n\nBring a warm and effortlessly relaxed feeling to your home with these cream yellow cotton linen curtains. Made from a natural cotton and linen fabric, they feature the beautiful texture and understated character associated with natural fibers. The soft creamy yellow tone sits gently between warm ivory and pale sunshine, adding brightness to a room without feeling too bold or saturated. Instead of looking overly formal or perfectly styled, the fabric falls into soft, natural folds that create an easygoing and lived-in atmosphere. This relaxed appearance makes the curtains a beautiful choice for INS-inspired interiors, natural homes, cream-toned spaces, French country rooms, cottage-style decor and modern farmhouse interiors. Softer and warmer than pure white, yet lighter than darker window treatments, the gentle color helps create a cozy and welcoming atmosphere while maintaining an airy feeling.\n\nLess\n", "images": [{"alt": "May include: A floor-length curtain featuring vertical stripes in mustard yellow and off-white. The fabric is hung from a metallic gold curtain rod with rings, creating deep, structured pleats that extend from the top to the bottom hem.", "src": "https://i.etsystatic.com/45174159/r/il/ea1003/8652543102/il_1588xN.8652543102_40a2.jpg"}, {"alt": "May include: A curtain panel featuring vertical stripes in alternating shades of soft yellow and off-white. The fabric has a visible woven texture and hangs in loose, draped folds, creating a series of soft, vertical pleats across the surface.", "src": "https://i.etsystatic.com/45174159/r/il/a07b6f/8388124320/il_794xN.8388124320_n7y9.jpg"}], "shops": [{"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL?ref=shop-header-name&listing_id=4556660960&from_page=listing"}, {"text": "", "url": "https://www.etsy.com/shop/WOGOL?ref=l2-about-shopname&from_page=listing"}], "title": "Mustard Yellow & Ivory Striped Curtains, English Cottage Semi Blackout Window Drapes", "source_url": "https://www.etsy.com/listing/4556660960/mustard-yellow-ivory-striped-curtains", "checked_at": "2026-10-13T05:23:23.951Z", "account": "P1", "shop": "WOGOL", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "707c76ca2483bb1b34bd0fb1371bf5d121d192168638d55442ddfcbb7b37df07"}, "listing_id": "4556660960", "new_title": "Mustard Yellow and Ivory Striped Curtain", "body": "Warm yellow and ivory stripes add a cheerful accent to this cotton-linen curtain from WOGOL. The listing is for one panel; check size and hanging options on Etsy.", "facebook_draft": "Mustard Yellow and Ivory Striped Curtain \u2014 Warm yellow and ivory stripes add a cheerful accent to this cotton-linen curtain from WOGOL. The listing is for one panel; check size and hanging options on Etsy. Browse: https://www.etsy.com/listing/4556660960/mustard-yellow-ivory-striped-curtains", "image_url": "https://i.etsystatic.com/45174159/r/il/ea1003/8652543102/il_1588xN.8652543102_40a2.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "icyndizhang", "board_id": "801218658646993070", "board_name": "CyndiZhangStudio", "category": "Curtains", "board_inspection_run": "38351026265"}, {"available": true, "details": "\nHighlights\nMade by WOGOL\nMaterials: Cotton, linen\n\nMaterial & Texture\nThis vintage-inspired curtain is crafted from thick cotton linen fabric, offering a natural texture with a soft yet structured drape. The linen blend brings breathable comfort while maintaining durability for everyday use. The vertical stripe pattern visually elongates the space, making ceilings appear higher and rooms more open. Pre-shrunk and carefully finished, the fabric resists deformation and provides a timeless, tactile quality ideal for refined interiors.\n\nStyle & Aesthetic\nDesigned with a balance of retro charm and modern simplicity, this striped curtain features a neutral color palette that blends effortlessly into various interior styles. Inspired by vintage, Japanese, and Nordic aesthetics, it complements wabi-sabi homes, French retro spaces, and minimalist natural interiors. The understated stripes add depth without overwhelming the space, creating a calm, elegant atmosphere that feels both nostalgic and contemporary.\n\nUsage & Customization\nPerfect for living rooms, bedrooms, studies, guest rooms, or boutique-style rentals, this curtain offers gentle light filtering and enhanced privacy. Custom sizing options are available to fit different window types and hanging preferences. Whether used in a cozy home or a stylish Airbnb, this custom curtain serves as both a functional window covering and a thoughtful decorative element that elevates the overall space.\n\nLess\n", "images": [{"alt": "May include: A floor-length curtain featuring a vertical striped pattern in alternating shades of dark olive green and off-white. The fabric hangs in uniform, pleated folds from a white header rail, covering a window area.", "src": "https://i.etsystatic.com/45174159/r/il/a6ceac/8652590258/il_1588xN.8652590258_md8o.jpg"}, {"alt": "May include: Floor-length curtains featuring a vertical striped pattern in shades of olive green, dark green, and white. The fabric hangs in uniform, pleated folds from a top rod, covering a large window that allows natural light to enter.", "src": "https://i.etsystatic.com/45174159/r/il/ac7433/8690100477/il_794xN.8690100477_n5di.jpg"}], "shops": [{"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL?ref=shop-header-name&listing_id=4439603695&from_page=listing"}, {"text": "WOGOL", "url": "https://www.etsy.com/shop/WOGOL"}], "title": "Green Striped Curtains, Linen Look Textured Window Drapes with Ivory Vertical Stripes", "source_url": "https://www.etsy.com/listing/4439603695/green-striped-curtains-linen-look", "checked_at": "2026-10-13T05:23:32.050Z", "account": "P1", "shop": "WOGOL", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "84b3411175ed87655002f01e48dfec3726e6f78446794445b9e987d6b4060de7"}, "listing_id": "4439603695", "new_title": "Olive Green and Ivory Striped Curtains", "body": "Textured green and ivory stripes create a relaxed window accent from WOGOL. See the original Etsy listing for panel quantities, sizes and color options.", "facebook_draft": "Olive Green and Ivory Striped Curtains \u2014 Textured green and ivory stripes create a relaxed window accent from WOGOL. See the original Etsy listing for panel quantities, sizes and color options. Browse: https://www.etsy.com/listing/4439603695/green-striped-curtains-linen-look", "image_url": "https://i.etsystatic.com/45174159/r/il/a6ceac/8652590258/il_1588xN.8652590258_md8o.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "icyndizhang", "board_id": "801218658646993070", "board_name": "CyndiZhangStudio", "category": "Curtains", "board_inspection_run": "38351026265"}, {"available": true, "details": "\nHighlights\nMaterials: Wood\n\nSolid Walnut Wood Rectangular Storage Box\nThis storage box is crafted from premium black walnut wood, featuring a minimalist rectangular design with a solid wood handle. It combines functionality and aesthetics, making it suitable for office desks, living rooms, and various home spaces.\n\n\u2726 Material & Craftsmanship\nMaterial: Solid Black Walnut Wood (premium hardwood)\nSurface Finish: Traditional mortise and tenon woodworking technique\nCraft: Hand-sanded and finely polished for a smooth, refined touch\nEach piece is carefully handcrafted and polished, preserving the natural grain and warm texture of real wood, offering a simple yet premium aesthetic.\n\n\u2726 Design Features\nClean rectangular silhouette with minimalist lines\nSolid wood handle for easy carrying and use\nUnique natural wood grain on every piece\nSturdy structure combining function and decoration\n\n\u2726 Usage Scenarios\nPerfect for organizing various spaces:\nOffice desk storage (stationery, documents, small items)\nLiving room organization (remote controls, daily essentials)\nBedroom storage (accessories, personal items)\nTea or coffee station organization\n\n\u2726 Style\nMinimalist design with natural wood aesthetics, creating a calm and elegant atmosphere suitable for modern, Nordic, and Japanese-style interiors.\n\n\u2726 Notes\nAs black walnut is a natural material, variations in grain, color, and knots are normal and unique to each piece\nHandcrafted item, slight dimensional variations may occur\nAvoid prolonged exposure to sunlight or humid environments\n\nLess\n", "images": [{"alt": "May include: A rectangular dark brown wooden storage tray with integrated side handles and visible finger joint corners. Inside the tray sits a small green plant in a light-colored ceramic pot, a tiny ceramic pitcher, and a round ceramic vase.", "src": "https://i.etsystatic.com/43671795/r/il/233a55/8107086354/il_1588xN.8107086354_2xoi.jpg"}, {"alt": "May include: A dark brown wooden storage bin with a rectangular base and high side panels featuring integrated cutout handles. The box is constructed with visible finger joints at the corners, showcasing a natural wood grain texture throughout the surface.", "src": "https://i.etsystatic.com/43671795/r/il/878f79/8110705321/il_794xN.8110705321_rb9x.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4511503152&from_page=listing"}, {"text": "", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=l2-about-shopname&from_page=listing"}], "title": "Walnut Open-Top Storage Bin with Cutout Handles, Minimal Wooden Desk Organizer", "source_url": "https://www.etsy.com/listing/4511503152/walnut-open-top-storage-bin-with-cutout", "checked_at": "2026-10-13T05:23:54.416Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "9b698004c3554024ab4286c7465bccad0109fab4b42d8a133845ff64445c9b57"}, "listing_id": "4511503152", "new_title": "Walnut Open-Top Storage Bin", "body": "A rectangular walnut storage bin with cutout side handles and visible corner joinery, from KoltCraftStudio. Keep desk or everyday items together. Natural grain varies; see sizes on Etsy.", "facebook_draft": "Walnut Open-Top Storage Bin \u2014 A rectangular walnut storage bin with cutout side handles and visible corner joinery, from KoltCraftStudio. Keep desk or everyday items together. Natural grain varies; see sizes on Etsy. Browse: https://www.etsy.com/listing/4511503152/walnut-open-top-storage-bin-with-cutout", "image_url": "https://i.etsystatic.com/43671795/r/il/233a55/8107086354/il_1588xN.8107086354_2xoi.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}, {"available": true, "details": "\nHighlights\nMade by KoltCraftStudio\nMaterials: Walnut\n\nBlack Walnut Multi-Function Desktop Storage Box\nCrafted from premium solid black walnut wood, each piece is carefully handmade with attention to detail. The natural wood grain is unique in every item, bringing a warm, elegant, and refined aesthetic to your living space.\n\nThis multi-purpose desktop organizer is designed to store remote controls, stationery, scissors, phones, glasses, and other small daily items. It helps keep your coffee table, desk, or living space clean and well-organized.\n\n\ud83d\udc49Features\nPremium Black Walnut Wood: Natural solid wood with unique grain patterns, eco-friendly and free from veneer\nExquisite Craftsmanship: Carefully polished surface with smooth rounded edges for safe and comfortable use\nMulti-Functional Storage: Ideal for office supplies, remote controls, accessories, and everyday essentials\nAnti-Slip Base Pads: Four protective pads at the bottom prevent sliding and protect furniture surfaces\nDurable Structure: Solid wood construction, stable and long-lasting, resistant to deformation\nCustom Engraving Available: Personalized text engraving for a unique and meaningful gift\n\n\ud83d\udc49Suitable For\nPerfect for coffee tables, office desks, bedside tables, entryways, and living room storage. It serves both as a practical organizer and a decorative piece, enhancing the overall style of your space.\n\n\ud83d\udc49Style & Color\nNatural black walnut finish with deep, elegant tones and visible wood grain. Suitable for modern minimalist, luxury, Scandinavian, and Japanese-inspired interiors.\n\n\ud83d\udc49Notes\nEach item is made from natural wood, so grain and color may vary slightly\nHandmade production may result in minor size differences\nAvoid prolonged exposure to sunlight or humid environments\nCustomized engraving items are non-returnable unless defective\n\nLess\n", "images": [{"alt": "May include: A rectangular dark brown wooden desk organizer with two internal compartments. The left side holds two black pens, while the right side holds three white pens. The wood features a visible grain pattern and smooth, rounded edges.", "src": "https://i.etsystatic.com/43671795/r/il/84d458/8016260809/il_1588xN.8016260809_ml81.jpg"}, {"alt": "May include: A rectangular wooden box with a rich brown grain pattern and smooth finish. The object features rounded edges and two small, dark, circular feet visible on the bottom corner, showcasing a natural wood texture and warm brown tones.", "src": "https://i.etsystatic.com/43671795/r/il/24035b/7968308832/il_794xN.7968308832_4dvs.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4497139834&from_page=listing"}, {"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio"}], "title": "Walnut Remote Control Caddy, Wood Remote Holder, Tabletop Organizer", "source_url": "https://www.etsy.com/listing/4497139834/walnut-remote-control-caddy-wood-remote", "checked_at": "2026-10-13T05:24:02.201Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "3801eea4024da34b0338f7f9fc14bd533d5d3039d02e34a30f4d8db7b3333080"}, "listing_id": "4497139834", "new_title": "Walnut Desktop Caddy", "body": "Two compartments and rounded edges define this walnut organizer from KoltCraftStudio. Use it for remote controls or desk essentials. See the original Etsy listing for details.", "facebook_draft": "Walnut Desktop Caddy \u2014 Two compartments and rounded edges define this walnut organizer from KoltCraftStudio. Use it for remote controls or desk essentials. See the original Etsy listing for details. Browse: https://www.etsy.com/listing/4497139834/walnut-remote-control-caddy-wood-remote", "image_url": "https://i.etsystatic.com/43671795/r/il/84d458/8016260809/il_1588xN.8016260809_ml81.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}, {"available": true, "details": "\nHighlights\nMade by KoltCraftStudio\nMaterials: Acacia, beech, walnut\n\nBring order and style to your entryway with this minimalist solid wood key holder tray. Designed for both functionality and aesthetics, it helps you keep everyday essentials organized while adding a warm, natural touch to your home.\n\n\ud83d\udc49Material & Craftsmanship\nMade from premium solid wood:\nWalnut\nBeech\nAcacia\nThis product is crafted from 100% solid wood (no veneer). Each piece is carefully hand-polished multiple times, resulting in a smooth surface and rounded edges for a refined and safe finish.\n\n\ud83d\udc49Functional Design\nA combined storage solution:\nUpper rack: for hanging keys, watches, necklaces\nLower tray: for storing glasses, lipsticks, perfumes, and small items\nKeeps frequently used items easy to access and neatly organized.\n\n\ud83d\udc49Available Styles\nCompact Style\nSquare Tray\nRectangular Tray\nDifferent shapes to suit various spaces and preferences.\n\n\ud83d\udc49Usage\nSuitable for organizing:\nKeys\nGlasses\nWatches\nJewelry\nCosmetics\nIdeal for entryways, bedrooms, desks, and vanity tables.\n\n\ud83d\udc49Design & Style\nNatural wood grain texture\nSimple and minimalist appearance\nBranch-inspired detail adds subtle decorative character\nEasy to match with different interior styles\n\n\ud83d\udc49Installation\nScrew-mounted structure\nEasy to install and remove\nStable and secure after installation\n\n\ud83d\udc49Details\nAnti-slip and anti-scratch pads on the bottom\nProtects surfaces and prevents sliding\nSmooth, hand-finished texture\n\n\ud83d\udc49Notes\nNatural wood grain and color may vary\nSlight size differences may occur due to handmade process\nAvoid prolonged exposure to moisture\n\nLess\n", "images": [{"alt": "May include: A dark brown wooden valet tray featuring a central vertical post with three angled pegs for hanging items. A silver key is hanging from one peg. A wristwatch with a black leather strap and black-rimmed eyeglasses rest on the tray.", "src": "https://i.etsystatic.com/43671795/r/il/012b1f/8015926937/il_1588xN.8015926937_pja0.jpg"}, {"alt": "May include: A dark brown wooden jewelry organizer stand with a central post featuring multiple branches for hanging items. The base is a rectangular tray holding a wristwatch, a pair of eyeglasses, a gold bracelet, two hoop earrings, and studs.", "src": "https://i.etsystatic.com/43671795/r/il/954fcd/8015926933/il_794xN.8015926933_f7h9.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4497091383&from_page=listing"}, {"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio"}], "title": "Solid Wood Catchall Tray, Entryway Key Holder, Wooden Valet Organizer, Desk Storage Tray", "source_url": "https://www.etsy.com/listing/4497091383/solid-wood-catchall-tray-entryway-key", "checked_at": "2026-10-13T05:24:09.787Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "e51ddcb3dc248f47d45f1a79b879a2065f4ba4837887a58d4128da1af7527e70"}, "listing_id": "4497091383", "new_title": "Wooden Valet Tray with Hanging Pegs", "body": "A tray base and branching pegs keep small accessories together in this KoltCraftStudio organizer. The listing offers several wood and tray options. See Etsy for details; pictured accessories are styling props.", "facebook_draft": "Wooden Valet Tray with Hanging Pegs \u2014 A tray base and branching pegs keep small accessories together in this KoltCraftStudio organizer. The listing offers several wood and tray options. See Etsy for details; pictured accessories are styling props. Browse: https://www.etsy.com/listing/4497091383/solid-wood-catchall-tray-entryway-key", "image_url": "https://i.etsystatic.com/43671795/r/il/012b1f/8015926937/il_1588xN.8015926937_pja0.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}, {"available": true, "details": "\nHighlights\nMade by KoltCraftStudio\nMaterials: Wood\n\nProduct\nMaterial: Cherry wood+Glass\nSize: As shown in the picture\n\nThis elegant storage box is expertly crafted from natural cherry wood, boasting a smooth, warm finish and unique, one-of-a-kind grain patterns. The clear glass lid allows you to display and access your items easily while adding a touch of sophistication to your space. It features sturdy hardware hinges for smooth and secure opening and closing. Perfect for organizing jewelry, rings, necklaces, watches, collectibles, tea bags, or personal desk items, it serves as both a functional organizer and a stylish home decor piece. Please note that natural wood grain, color variations, and knots are inherent characteristics of solid wood and add to the unique charm of each box.\n\nCUSTOM ENGRAVING\nWe offer laser engraving customization for this product.\nYou can personalize the item with:\n\u2022 Name\n\u2022 Logo\n\u2022 Short text\n\u2022 Special date\n\u2022 Simple design\nThis makes it a perfect personalized gift for friends, family, weddings, or business use.\n\nMATERIAL & COLOR\nDue to the natural grain of wood, each piece will have unique patterns and slight color variations.\nThis makes every item truly one of a kind.\n\nHANDMADE PRODUCT\nEach item is carefully handcrafted and polished by hand.\nSmall natural imperfections, wood grain differences, or tiny variations are normal and are part of the beauty of handmade wooden products.\n\nCARE INSTRUCTIONS\n\u2022 Keep away from excessive moisture\n\u2022 Clean with a dry or slightly damp cloth\n\u2022 Do not soak in water\n\u2022 Avoid prolonged direct sunlight\n\nSHIPPING\nProcessing Time: 3\u20137 business days.\nAll items are carefully packed to ensure they arrive safely.\nIf you have any questions about your order, please feel free to contact us.\n\nPLEASE NOTE\n\u2022 Props shown in photos are not included.\n\u2022 Please check the size carefully before ordering.\n\u2022 Due to lighting and screen differences, colors may appear slightly different.\n\nLess\n", "images": [{"alt": "May include: Wooden display boxes with glass tops. The boxes are rectangular and made of light-colored wood. The glass tops allow for a clear view of the contents. The boxes are arranged on a wooden surface.", "src": "https://i.etsystatic.com/43671795/r/il/e7d0a7/7854864753/il_1588xN.7854864753_kj0y.jpg"}, {"alt": "May include: A wooden display box with a hinged lid and a glass front. The box is made of light brown wood with visible grain and is partially open, revealing the interior. The box is designed to showcase items.", "src": "https://i.etsystatic.com/43671795/r/il/33a0ef/7669883916/il_794xN.7669883916_2jwz.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4451568739&from_page=listing"}, {"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio"}], "title": "Cherry Wood Storage Box with Clear Glass Lid, Wooden Jewelry Organizer", "source_url": "https://www.etsy.com/listing/4451568739/cherry-wood-storage-box-with-clear-glass", "checked_at": "2026-10-13T05:24:19.233Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "649b7a50a8c0faa5a12ab79a9bdaa37f9a0a25748f9f536c8c304ef34afca8e5"}, "listing_id": "4451568739", "new_title": "Cherry Wood Box with Glass Lid", "body": "A clear glass lid displays the contents of this cherry wood storage box from KoltCraftStudio. Choose a size for jewelry or small desk items. Natural wood grain varies; see Etsy for details.", "facebook_draft": "Cherry Wood Box with Glass Lid \u2014 A clear glass lid displays the contents of this cherry wood storage box from KoltCraftStudio. Choose a size for jewelry or small desk items. Natural wood grain varies; see Etsy for details. Browse: https://www.etsy.com/listing/4451568739/cherry-wood-storage-box-with-clear-glass", "image_url": "https://i.etsystatic.com/43671795/r/il/e7d0a7/7854864753/il_1588xN.7854864753_kj0y.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}, {"available": true, "details": "\nHighlights\nMade by KoltCraftStudio\nMaterials: Wood\n\nProduct\nMaterial: Walnut wood\nSize: As shown in the picture\n\nEmbodying a perfect blend of ins-famous boho charm and rustic vintage aesthetics, this catchall tray elevates any space it occupies. Its minimalist design with clean lines fits seamlessly into various decor styles\u2014from Scandinavian modern to farmhouse chic. Use it as a stylish entryway key drop to end frantic searches, a serene bedside tray for nightly jewelry, or a sophisticated desktop organizer for pens, watches, and airpods. It also serves as a beautiful vanity tray for perfumes and trinkets, ensuring your essentials are always neatly displayed yet within easy reach.\n\n*Note:\n1.All products in our store are photographed in real life. Due to differences in shooting lighting and phone/computer display screens, there may be slight color variations, which is a normal phenomenon.Please consider carefully before purchasing if you mind.\n2.This product is made of solid wood. Variations in wood grain, knots, and color differences may occur. These are normal and unavoidable. Please consider carefully before purchasing if you mind. 3.Due to differences in measuring tools, there may be a 1-3mm error in the product specifications. Please consider carefully before purchasing if you mind.\n\nLess\n", "images": [{"alt": "May include: Two wooden bowls of different shapes, one oval and one round, sit on a white surface. The bowls are filled with small items, including a tube of cream, a lipstick, a ring, and a card with the text \"QUE SERA SERA\".", "src": "https://i.etsystatic.com/43671795/r/il/0d80f9/8001352977/il_1588xN.8001352977_luk1.jpg"}, {"alt": "May include: Two wooden oval bowls. The bowl on the left is a light brown color, and the bowl on the right is a dark brown color. Both bowls have a smooth, polished finish and are empty. The bowls are made of wood and are likely for serving food.", "src": "https://i.etsystatic.com/43671795/r/il/a248c1/8001352995/il_794xN.8001352995_aai1.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4434422856&from_page=listing"}, {"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio"}], "title": "Walnut Wood Storage Tray, Oval Wooden Jewelry Plate ,Entryway Key Organizer", "source_url": "https://www.etsy.com/listing/4434422856/walnut-wood-storage-tray-oval-wooden", "checked_at": "2026-10-13T05:24:30.314Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1587], "sha256": "98fad203f94d46fbe739bd4fe4bd3ab215dfcbfa3fa974689136b831231e20aa"}, "listing_id": "4434422856", "new_title": "Walnut Catchall Tray", "body": "Rounded walnut trays offer a place for keys, jewelry and small essentials. From KoltCraftStudio, with multiple shapes and sizes listed on Etsy. Natural grain and color vary.", "facebook_draft": "Walnut Catchall Tray \u2014 Rounded walnut trays offer a place for keys, jewelry and small essentials. From KoltCraftStudio, with multiple shapes and sizes listed on Etsy. Natural grain and color vary. Browse: https://www.etsy.com/listing/4434422856/walnut-wood-storage-tray-oval-wooden", "image_url": "https://i.etsystatic.com/43671795/r/il/0d80f9/8001352977/il_1588xN.8001352977_luk1.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}, {"available": true, "details": "\nHighlights\nMade by KoltCraftStudio\nMaterials: Walnut, wood\n\nThis Walnut Wood Floss Holder is crafted from natural solid wood, designed for organizing toothpicks, dental floss, and small everyday essentials. A simple and functional desktop storage box that combines natural texture with minimalist design.\n\n\u2726Material & Craftsmanship\nMade from premium solid walnut wood, each piece features unique natural grain patterns.\nThe hand-polished surface ensures a smooth, splinter-free finish with a warm and natural touch.\n\n\u2726Features\nDual-compartment design for separate storage of toothpicks and dental floss\nMulti-purpose organizer for small everyday essentials\nMinimalist design with natural wood texture\nSealed structure helps keep items clean and dust-free\nFour-leaf clover metal accent adds a subtle decorative detail\n\n\u2726Usage\nIdeal for desktop organization:\nstudy desk, office desk, vanity table, coffee table, and kitchen counter.\nHelps keep small items neatly stored and easily accessible.\n\n\u2726Style\nMinimalist natural wood design with a light luxury aesthetic, suitable for modern, Scandinavian, and Japanese-style interiors.\n\n\u2726Notes\nEach item has natural variations in wood grain and color\nAvoid long-term exposure to moisture\nClean with a soft dry cloth only\nSlight measurement differences may occur due to handmade production\n\nLess\n", "images": [{"alt": "May include: A cylindrical dark brown wooden container with a removable lid. The base holds a cluster of light brown wooden toothpicks and a white plastic dental pick. The wood features a visible grain pattern and a smooth, polished finish.", "src": "https://i.etsystatic.com/43671795/r/il/f241a6/8356178165/il_1588xN.8356178165_fhjr.jpg"}, {"alt": "May include: A cylindrical dark brown wooden organizer featuring a smooth finish and a single interior divider that creates two distinct semi-circular compartments for storage. The natural wood grain is visible across the exterior surface.", "src": "https://i.etsystatic.com/43671795/r/il/af9a90/8308283848/il_794xN.8308283848_hakr.jpg"}], "shops": [{"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio?ref=shop-header-name&listing_id=4528223141&from_page=listing"}, {"text": "KoltCraftStudio", "url": "https://www.etsy.com/shop/KoltCraftStudio"}], "title": "Walnut Floss Holder Toothpick Box | Wooden Dental Organizer for Desk", "source_url": "https://www.etsy.com/listing/4528223141/walnut-floss-holder-toothpick-box-wooden", "checked_at": "2026-10-13T05:24:38.397Z", "account": "P2", "shop": "KoltCraftStudio", "image_check": {"http_status": 200, "size": [1588, 1588], "sha256": "04bd3083b6cfb32ff2168c87c6caebd4fd93272e7dcf6bb9985577d15cb8591e"}, "listing_id": "4528223141", "new_title": "Walnut Small-Item Organizer with Lid", "body": "A cylindrical walnut container with two interior compartments and a removable lid, from KoltCraftStudio. Intended for toothpicks, floss picks or other small items. See Etsy for product details.", "facebook_draft": "Walnut Small-Item Organizer with Lid \u2014 A cylindrical walnut container with two interior compartments and a removable lid, from KoltCraftStudio. Intended for toothpicks, floss picks or other small items. See Etsy for product details. Browse: https://www.etsy.com/listing/4528223141/walnut-floss-holder-toothpick-box-wooden", "image_url": "https://i.etsystatic.com/43671795/r/il/f241a6/8356178165/il_1588xN.8356178165_fhjr.jpg", "visual_verified": true, "unresolved_reason": null, "handle": "sailing_981", "board_id": "863494997243989843", "board_name": "storage", "category": "Home Storage", "board_inspection_run": "38349053287"}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>10 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','seven-day-20261013-1'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261013',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261013',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
